import{_ as r,o,c as n,j as t,a as e,a2 as a}from"./chunks/framework.CXZjg2r3.js";const b=JSON.parse('{"title":"🟢 第 1 章 · 账号类型与认证","description":"","frontmatter":{},"headers":[],"relativePath":"mp-account/01-account-types.md","filePath":"mp-account/01-account-types.md","lastUpdated":1792667591000}'),l={name:"mp-account/01-account-types.md"};function i(p,s,d,c,g,h){return o(),n("div",null,[...s[0]||(s[0]=[t("h1",{id:"🟢-第-1-章-·-账号类型与认证",tabindex:"-1"},[e("🟢 第 1 章 · 账号类型与认证 "),t("a",{class:"header-anchor",href:"#🟢-第-1-章-·-账号类型与认证","aria-label":'Permalink to "🟢 第 1 章 · 账号类型与认证"'},"​")],-1),t("div",{class:"tip custom-block"},[t("p",{class:"custom-block-title"},"本章信息"),t("p",null,"难度：🟢 入门 · 预计学习 30 分钟 · 前置：第 0 章 · 环境准备")],-1),t("svg",{viewBox:"0 0 760 240",xmlns:"http://www.w3.org/2000/svg",width:"100%",role:"img","aria-label":"第 1 章漫画：账号类型与认证"},[t("g",null,[t("rect",{x:"10",y:"10",width:"360",height:"220",rx:"12",fill:"#F8FAFC",stroke:"#E2E8F0"}),t("text",{x:"26",y:"34","font-size":"14",fill:"#94A3B8","font-family":"sans-serif"},"1"),t("path",{d:"M70 90 Q76 76 86 74",stroke:"#3B82F6","stroke-width":"3",fill:"none","stroke-linecap":"round"}),t("circle",{cx:"70",cy:"112",r:"24",fill:"#3B82F6"}),t("rect",{x:"48",y:"140",width:"44",height:"36",rx:"13",fill:"#3B82F6"}),t("circle",{cx:"62",cy:"106",r:"2.6",fill:"#1E293B"}),t("circle",{cx:"78",cy:"106",r:"2.6",fill:"#1E293B"}),t("path",{d:"M60 120 Q63 124 66 120 Q69 116 72 120 Q75 124 78 120",stroke:"#1E293B","stroke-width":"2",fill:"none","stroke-linecap":"round"}),t("path",{d:"M116 100 L96 110 L116 120 Z",fill:"#FFFFFF",stroke:"#CBD5E1","stroke-width":"1.5"}),t("rect",{x:"116",y:"56",width:"238",height:"100",rx:"10",fill:"#FFFFFF",stroke:"#CBD5E1"}),t("text",{x:"132",y:"82","font-size":"13",fill:"#334155","font-family":"sans-serif"},"注册让我选主体类型"),t("text",{x:"132",y:"104","font-size":"13",fill:"#334155","font-family":"sans-serif"},"订阅号服务号有啥区别"),t("text",{x:"132",y:"126","font-size":"13",fill:"#334155","font-family":"sans-serif"},"我全都选懵了")]),t("g",null,[t("rect",{x:"390",y:"10",width:"360",height:"220",rx:"12",fill:"#F8FAFC",stroke:"#E2E8F0"}),t("text",{x:"406",y:"34","font-size":"14",fill:"#94A3B8","font-family":"sans-serif"},"2"),t("circle",{cx:"450",cy:"112",r:"24",fill:"#F59E0B"}),t("rect",{x:"428",y:"140",width:"44",height:"36",rx:"13",fill:"#F59E0B"}),t("line",{x1:"441",y1:"100",x2:"441",y2:"114",stroke:"#1E293B","stroke-width":"2","stroke-linecap":"round"}),t("line",{x1:"459",y1:"100",x2:"459",y2:"114",stroke:"#1E293B","stroke-width":"2","stroke-linecap":"round"}),t("circle",{cx:"447",cy:"107",r:"2.4",fill:"#1E293B"}),t("circle",{cx:"453",cy:"107",r:"2.4",fill:"#1E293B"}),t("path",{d:"M442 122 Q450 130 458 122",stroke:"#1E293B","stroke-width":"2",fill:"none","stroke-linecap":"round"}),t("path",{d:"M496 100 L476 110 L496 120 Z",fill:"#FFFFFF",stroke:"#CBD5E1","stroke-width":"1.5"}),t("rect",{x:"496",y:"56",width:"238",height:"100",rx:"10",fill:"#FFFFFF",stroke:"#CBD5E1"}),t("text",{x:"512",y:"82","font-size":"13",fill:"#334155","font-family":"sans-serif"},"一张表分清四种号"),t("text",{x:"512",y:"104","font-size":"13",fill:"#334155","font-family":"sans-serif"},"个人先玩订阅号"),t("text",{x:"512",y:"126","font-size":"13",fill:"#334155","font-family":"sans-serif"},"权限去接口权限页看")])],-1),a(`<h2 id="🎯-学习目标" tabindex="-1">🎯 学习目标 <a class="header-anchor" href="#🎯-学习目标" aria-label="Permalink to &quot;🎯 学习目标&quot;">​</a></h2><p>读完本章，你将能够：</p><ul><li>能说出<strong>订阅号、服务号、企业微信、小程序</strong>的定位差异</li><li>能判断<strong>个人主体</strong>能注册哪几种账号</li><li>能说清<strong>认证</strong>前后接口能力的三档差异</li><li>能在后台找到「<strong>接口权限</strong>」页，并安全地保管 AppID 与 AppSecret</li></ul><h2 id="📇-术语卡" tabindex="-1">📇 术语卡 <a class="header-anchor" href="#📇-术语卡" aria-label="Permalink to &quot;📇 术语卡&quot;">​</a></h2><table tabindex="0"><thead><tr><th>术语</th><th>白话解释</th></tr></thead><tbody><tr><td>主体</td><td>注册时登记的「你是谁」：个人、企业、政府等，决定了你能开的账号类型</td></tr><tr><td>订阅号</td><td>偏内容媒体的号，一天能群发一次，被折叠在「订阅号消息」文件夹里</td></tr><tr><td>服务号</td><td>偏对外服务的号，一个月群发四次，直接躺在会话列表里，接口权限最多</td></tr><tr><td>企业微信</td><td>面向企业内部员工办公协同的工具，不面向公众号粉丝</td></tr><tr><td>认证</td><td>每年花一笔钱向微信证明「我是正规组织」，换来更多高级接口</td></tr><tr><td>接口权限</td><td>后台里的一份「能力清单」，哪些接口能用、哪些不能用一目了然</td></tr><tr><td>AppID / AppSecret</td><td>账号的「用户名 + 密钥」，调接口时的身份凭证，Secret 绝不能泄露</td></tr></tbody></table><h2 id="🧭-四种账号一张表看清" tabindex="-1">🧭 四种账号一张表看清 <a class="header-anchor" href="#🧭-四种账号一张表看清" aria-label="Permalink to &quot;🧭 四种账号一张表看清&quot;">​</a></h2><table tabindex="0"><thead><tr><th>对比项</th><th>订阅号</th><th>服务号</th><th>企业微信</th><th>小程序</th></tr></thead><tbody><tr><td>定位</td><td>自媒体，天天推内容</td><td>对外服务窗口，像银行柜台</td><td>企业内部办公协同</td><td>即点即用的小应用</td></tr><tr><td>谁能注册</td><td>个人、组织</td><td>仅组织</td><td>仅组织</td><td>个人、组织</td></tr><tr><td>群发次数</td><td>1 次 / 天</td><td>4 次 / 月</td><td>面向内部成员，无群发概念</td><td>无群发概念</td></tr><tr><td>在哪显示</td><td>折叠进「订阅号消息」</td><td>直接躺在会话列表</td><td>独立 App</td><td>独立入口，搜索 / 扫码进</td></tr><tr><td>微信支付</td><td>不支持</td><td>认证后可申请</td><td>走企业内部方案</td><td>支持电商等场景</td></tr><tr><td>认证费用</td><td>个人无法认证；组织认证 300 元 / 年</td><td>300 元 / 次 / 年</td><td>有独立认证体系</td><td>300 元 / 次</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">注意</p><p>表中群发次数、认证费用等数字会随官方政策调整，<strong>一律以官方文档和后台实际展示为准</strong>。做决策前去官方说明页核对一遍。</p></div><h3 id="一分钟选出该注册哪种" tabindex="-1">一分钟选出该注册哪种 <a class="header-anchor" href="#一分钟选出该注册哪种" aria-label="Permalink to &quot;一分钟选出该注册哪种&quot;">​</a></h3><p>拿不准就用这三个问题过一遍：</p><ol><li><strong>每天想发文章吗？</strong> 想做内容、日更推文 → 订阅号</li><li><strong>要对外提供服务和支付吗？</strong> 底部菜单跳转、模板通知、微信支付一个都不能少 → 认证服务号（需要组织资质）</li><li><strong>只是给自己团队用？</strong> 面向员工而非粉丝 → 企业微信；想做即点即用的工具 → 小程序</li></ol><p>本课程走「公众号 H5 / 接口开发」路线，所以主角是<strong>订阅号 + 测试号</strong>的组合拳。</p><h2 id="👤-个人主体能选什么" tabindex="-1">👤 个人主体能选什么 <a class="header-anchor" href="#👤-个人主体能选什么" aria-label="Permalink to &quot;👤 个人主体能选什么&quot;">​</a></h2><p>拿着个人身份证，你能注册的是：</p><ul><li>✅ <strong>订阅号（个人）</strong>——本课程的主角，学接口开发够用</li><li>✅ <strong>小程序（个人）</strong>——另一条课程线的主角</li><li>❌ <strong>服务号</strong>——仅组织可注册，个人没有入口</li><li>❌ <strong>企业微信</strong>——需要组织资质</li></ul><p><strong>个人订阅号权限少怎么办？</strong> 公众平台提供了「<strong>测试号</strong>」（俗称沙盒）：在后台搜索「公众平台测试帐号」即可申请，它几乎开放全部接口（网页授权、模板消息、自定义菜单都有），不用认证、不用备案。<strong>后面学到权限不够的章节，就用测试号练手。</strong></p><h2 id="🔑-认证带来的接口差异" tabindex="-1">🔑 认证带来的接口差异 <a class="header-anchor" href="#🔑-认证带来的接口差异" aria-label="Permalink to &quot;🔑 认证带来的接口差异&quot;">​</a></h2><p>账号能力大致分三档，越往上门槛越高：</p><table tabindex="0"><thead><tr><th>档位</th><th>能力举例</th><th>谁有</th></tr></thead><tbody><tr><td>基础能力</td><td>自定义菜单、素材管理、被动回复消息</td><td>所有公众号，不看认证</td></tr><tr><td>认证解锁</td><td>获取用户基本信息、用户管理、部分高级接口</td><td>认证后的订阅号 / 服务号</td></tr><tr><td>服务号专属</td><td>网页授权 OAuth、JSSDK（分享 / 定位 / 支付）、模板消息、微信支付</td><td>仅<strong>认证服务号</strong></td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">给零基础的你</p><p>个人订阅号没有网页授权和模板消息权限，<strong>这不是你操作错了</strong>。课程第 3、4、6 章会用测试号带你把流程完整跑一遍，学到的代码一模一样，将来换成认证服务号直接可用。</p></div><h3 id="现在就申请一个测试号" tabindex="-1">现在就申请一个测试号 <a class="header-anchor" href="#现在就申请一个测试号" aria-label="Permalink to &quot;现在就申请一个测试号&quot;">​</a></h3><p>测试号（沙盒）是官方给开发者的「练号」，两分钟就能开通：</p><p><strong>第 1 步：进入沙盒页</strong></p><p>登录后台，在「设置与开发」里搜索或找到「<strong>公众平台测试帐号</strong>」，点击进入。</p><blockquote><p>✅ <strong>你应该看到：</strong> 一个朴素的测试号管理页，顶部显示测试号的 appID 和 appsecret，下方是「接口配置信息」「网页授权获取用户基本信息」等测试入口。</p></blockquote><p><strong>第 2 步：记录测试号凭证</strong></p><p>把测试号的 appID、appsecret 抄进你的本地私密笔记——第 2 章起它们会替代正式号凭证出场。</p><p><strong>第 3 步：扫码关注测试号</strong></p><p>手机微信扫描沙盒页提供的二维码，关注这个测试号。</p><blockquote><p>✅ <strong>你应该看到：</strong> 沙盒页「用户列表」里出现你的微信昵称——从现在起，你就是这个测试号的第一个粉丝。</p></blockquote><p>测试号无须认证、无须备案域名，几乎开放全部接口（限额另计，以官方文档为准），是后面五章的「主战场」。</p><div class="warning custom-block"><p class="custom-block-title">注意</p><p>测试号仅用于开发调试，不要拿它对外提供服务或投放真实用户；正式功能必须迁移到认证后的正式账号。</p></div><h3 id="认证怎么办理-概览" tabindex="-1">认证怎么办理（概览） <a class="header-anchor" href="#认证怎么办理-概览" aria-label="Permalink to &quot;认证怎么办理（概览）&quot;">​</a></h3><p>将来有组织资质、要上正式项目时，认证流程大致三步（入口位置与所需材料以官方文档为准）：</p><p><strong>第 1 步：进入认证入口</strong></p><p>后台「设置与开发 → 微信认证」，点「开通」。</p><blockquote><p>✅ <strong>你应该看到：</strong> 认证向导页，列出所需材料（主体资质、对公账户、运营者信息等）。</p></blockquote><p><strong>第 2 步：填写资料并支付认证费</strong></p><p>按向导上传材料、支付 300 元审核费（金额以官方文档为准）。</p><blockquote><p>✅ <strong>你应该看到：</strong> 支付成功页，状态变为「审核中」。</p></blockquote><p><strong>第 3 步：等待审核结果</strong></p><p>第三方审核机构会在几个工作日内联系你核实（时限以官方文档为准）。</p><blockquote><p>✅ <strong>你应该看到：</strong> 后台认证状态变为「已认证」，接口权限页随之多出一批「已获得」。</p></blockquote><div class="warning custom-block"><p class="custom-block-title">注意</p><p>认证有费用且<strong>按年计费</strong>，未按时年审会失去对应接口权限。个人开发者学习阶段不必花这笔钱，用测试号即可。</p></div><h2 id="🧾-接口权限页在哪里看" tabindex="-1">🧾 接口权限页在哪里看 <a class="header-anchor" href="#🧾-接口权限页在哪里看" aria-label="Permalink to &quot;🧾 接口权限页在哪里看&quot;">​</a></h2><p><strong>第 1 步：登录后台</strong></p><p>浏览器打开 <code>https://mp.weixin.qq.com</code>，扫码登录。</p><blockquote><p>✅ <strong>你应该看到：</strong> 公众号后台首页。</p></blockquote><p><strong>第 2 步：进入接口权限页</strong></p><p>左侧菜单点「<strong>设置与开发</strong>」→「<strong>接口权限</strong>」（后台改版后路径可能微调，以实际界面为准）。</p><blockquote><p>✅ <strong>你应该看到：</strong> 一张长长的权限清单，每行一个能力（如「获取用户基本信息」「网页服务 → 网页授权」），右侧标注「已获得」或「未获得」。</p></blockquote><p><strong>第 3 步：看懂三列关键信息</strong></p><ul><li><strong>接口名称</strong>：能力叫什么</li><li><strong>状态</strong>：能不能用</li><li><strong>说明</strong>：有没有频次、场景限制（限额数字以官方文档为准）</li></ul><p><strong>第 4 步：拿到 AppID、保管 AppSecret</strong></p><p>仍在「设置与开发」→「<strong>基本配置</strong>」页，能看到开发者 ID（AppID）；AppSecret 首次需要点「重置」生成，<strong>只显示一次</strong>。</p><blockquote><p>✅ <strong>你应该看到：</strong> AppSecret 出现在页面上。立刻把它存进本地私密文件或密码管理器，<strong>不要</strong>提交到代码仓库、不要发到聊天群。</p></blockquote><div class="warning custom-block"><p class="custom-block-title">注意</p><p>AppSecret 一旦泄露，别人可以冒用你的账号调所有接口。重置 Secret 会让旧的立即失效——<strong>已上线的服务会当场趴窝</strong>，正式项目重置前先想清楚。</p></div><h2 id="💻-动手实践-盘点你的账号家底" tabindex="-1">💻 动手实践：盘点你的账号家底 <a class="header-anchor" href="#💻-动手实践-盘点你的账号家底" aria-label="Permalink to &quot;💻 动手实践：盘点你的账号家底&quot;">​</a></h2><p><strong>从零运行步骤：</strong></p><ol><li>登录公众号后台，进入「设置与开发 → 接口权限」</li><li>在清单里找到下面这几项，把状态抄进你的笔记：自定义菜单、网页授权、模板消息（或订阅通知）、获取用户基本信息、微信支付</li><li>再到「基本配置」页记下 <strong>AppID</strong>，重置并保存 <strong>AppSecret</strong></li><li>对照下面的表格模板，填出你自己账号的「能力清单」：</li></ol><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>我的账号：订阅号（个人主体）</span></span>
<span class="line"><span>--------------------------------------</span></span>
<span class="line"><span>能力               状态        谁能用</span></span>
<span class="line"><span>自定义菜单         已获得      ✅ 我自己</span></span>
<span class="line"><span>网页授权           未获得      ❌ 需认证服务号 → 用测试号练</span></span>
<span class="line"><span>模板消息           未获得      ❌ 需认证服务号 → 用测试号练</span></span>
<span class="line"><span>获取用户基本信息   视后台展示   （填你看到的）</span></span>
<span class="line"><span>微信支付           不支持      ❌ 与订阅号无缘</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br></div></div><blockquote><p>✅ <strong>你应该看到：</strong> 一份自己账号的真实能力清单，并且明确了「哪些学起来没问题、哪些要用测试号」。</p></blockquote><h2 id="✏️-分级练习" tabindex="-1">✏️ 分级练习 <a class="header-anchor" href="#✏️-分级练习" aria-label="Permalink to &quot;✏️ 分级练习&quot;">​</a></h2><ol><li>🟢 <strong>跟做型</strong>：进入接口权限页，抄录 5 个权限的名称和状态，感受一下「能力清单」长什么样。</li><li>🟡 <strong>修改型</strong>：朋友想做一个「到店预约 + 会员通知」的服务，对照四种账号的对比表，帮他选出该注册的账号类型，并写出三条理由。</li><li>🔴 <strong>创作型</strong>：申请一个<strong>公众平台测试号</strong>，把它的接口权限列表和你正式订阅号对比，列出 3 个「测试号有、正式号没有」的接口，写进笔记。</li></ol><h2 id="⚠️-常见坑" tabindex="-1">⚠️ 常见坑 <a class="header-anchor" href="#⚠️-常见坑" aria-label="Permalink to &quot;⚠️ 常见坑&quot;">​</a></h2><ul><li><strong>AppSecret 忘了保存就关了页面</strong> → Secret 只显示一次，只能重置 → 重置后立刻存好；正式项目要先评估旧 token 失效影响</li><li><strong>个人订阅号找不到「网页授权」入口</strong> → 权限本身不存在，不是你眼花 → 学习期用测试号（见练习 3），正式上线换认证服务号</li><li><strong>拿个人身份证注册服务号</strong> → 服务号仅组织主体可注册 → 学习用订阅号，或以个体工商户等主体注册</li><li><strong>账号名称注册失败提示被占用</strong> → 名称全局唯一 → 换一个更独特的名字，命名规则以官方文档为准</li></ul><h2 id="下一章预告" tabindex="-1">下一章预告 <a class="header-anchor" href="#下一章预告" aria-label="Permalink to &quot;下一章预告&quot;">​</a></h2><p>家底盘清了。下一章正式点火：用 AppID 和 AppSecret 换到第一张 access_token「门票」，调通第一个写接口——给你的公众号亲手造一排自定义菜单。</p>`,68)])])}const f=r(l,[["render",i]]);export{b as __pageData,f as default};
